using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using MarketSphere.Domain.Entities.Infrastructure;
namespace MarketSphere.Infrastructure.Persistence.Configurations.Infrastructure;
public sealed class ApprovalRequestConfiguration : IEntityTypeConfiguration<ApprovalRequest> { public void Configure(EntityTypeBuilder<ApprovalRequest> builder) { builder.ToTable("ApprovalRequests", t => t.HasCheckConstraint("CK_ApprovalRequests_CurrentStep", "[CurrentStepNo] > 0")); builder.HasKey(x => x.ApprovalRequestID); builder.Property(x => x.ReferenceType).HasMaxLength(100).IsRequired(); builder.Property(x => x.ApprovalType).HasConversion<int>(); builder.Property(x => x.Status).HasConversion<int>(); builder.Property(x => x.RowVersion).IsRowVersion(); builder.HasIndex(x => new { x.ReferenceType, x.ReferenceID, x.ApprovalType }).IsUnique().HasFilter("[Status] IN (1,2)"); builder.HasIndex(x => new { x.Status, x.CurrentStepNo, x.RequestedAt }); builder.HasOne(x => x.ApprovalPolicy).WithMany(x => x.Requests).HasForeignKey(x => x.ApprovalPolicyID).OnDelete(DeleteBehavior.Restrict); builder.HasOne(x => x.RequestedByUser).WithMany().HasForeignKey(x => x.RequestedByUserID).OnDelete(DeleteBehavior.Restrict); } }
